SubProceso Potencia(base Como Entero, exponente Como Entero) Como Entero
    Si exponente = 0 Entonces
        Retornar 1;
    SiNo
        Retornar base * Potencia(base, exponente - 1);
    FinSi
FinSubProceso

Proceso CalcularPotencia
    Definir base Como Entero;
    Definir exponente Como Entero;
    Leer base;
    Leer exponente;
    Escribir Potencia(base, exponente);
FinProceso
